-- =====================================================
-- KITCHEN WRAP MASTERS — Orders Table
-- Run this once in your Supabase SQL Editor:
-- https://supabase.com/dashboard/project/jxhrbkhzmhnrlqcxgvxa/sql
-- =====================================================

create table if not exists orders (
  -- Primary key — PayFast's own payment ID
  id                  bigserial primary key,

  -- PayFast identifiers
  pf_payment_id       text unique not null,
  pf_payment_status   text not null default 'COMPLETE',

  -- Order reference (generated by our checkout, format: KWM-timestamp-random)
  order_reference     text not null,

  -- Amounts (stored in Rands, 2 decimal places)
  amount_gross        numeric(10,2) not null,
  amount_fee          numeric(10,2),
  amount_net          numeric(10,2),

  -- Customer details
  customer_first_name text,
  customer_last_name  text,
  customer_email      text,
  customer_phone      text,

  -- Delivery details
  delivery_method     text,   -- 'courier' or 'collect'
  delivery_address    text,
  delivery_city       text,
  delivery_province   text,
  delivery_postal     text,

  -- Order contents (full cart as JSON)
  -- Each item: { id, name, variant, price, qty, colour, vinylSize, installationVideo }
  items               jsonb not null default '[]',

  -- Order notes from customer
  notes               text,

  -- Item name sent to PayFast (summary string)
  item_name           text,

  -- Fulfilment status (managed by you in Supabase dashboard)
  fulfilment_status   text not null default 'pending',
  -- Values: 'pending' | 'processing' | 'shipped' | 'collected' | 'completed' | 'cancelled'

  -- Timestamps
  created_at          timestamptz not null default now(),
  updated_at          timestamptz not null default now()
);

-- Auto-update updated_at on any row change
create or replace function update_updated_at()
returns trigger language plpgsql as $$
begin
  new.updated_at = now();
  return new;
end;
$$;

create trigger orders_updated_at
  before update on orders
  for each row execute function update_updated_at();

-- Index for fast lookup by reference and email
create index if not exists orders_order_reference_idx on orders(order_reference);
create index if not exists orders_customer_email_idx  on orders(customer_email);
create index if not exists orders_created_at_idx      on orders(created_at desc);

-- Row Level Security — service_role can do everything, anon can do nothing
alter table orders enable row level security;

-- No public read/write — only your server (service_role key) touches this table
-- The notify function uses the service_role key and bypasses RLS automatically.

-- =====================================================
-- DONE. After running this you should see an 'orders'
-- table in your Supabase Table Editor.
